// src/utils/AppErr.ts
class AppErr extends Error {
  statusCode;
  data;
  appErr;
  status;
  constructor(message, statusCode, data) {
    super();
    this.message = message;
    this.statusCode = statusCode;
    this.data = null;
    this.appErr = true;
    this.status = false;
    if (data) {
      this.data = data;
    } else {
      this.data = null;
    }
  }
}
var customError = (msg, data) => {
  throw new AppErr(msg, data);
};

