// src/guard/auth.guard.ts
var isAdminAuthenticated = async (Context) => {
  const { set, headers, request } = Context;
  if (!headers.authorization) {
    set.status = 401;
    return {
      status: false,
      message: "Unauthorized",
      data: "No access token"
    };
  }
  let token = headers.authorization.replace("Bearer ", "");
  const jwt2 = jwt_default.verify(token);
  if (!jwt2) {
    set.status = 401;
    return {
      status: false,
      message: "Unauthorized.",
      data: "Invalid access token"
    };
  }
  const { _id } = jwt2;
  if (!_id) {
    set.status = 401;
    return {
      status: false,
      message: "Unauthorized",
      data: "access token is empty"
    };
  }
  const user = await Admin_default.findById(jwt2._id).populate(["role", "doctor"]);
  if (!user) {
    set.status = 401;
    return {
      status: false,
      message: "Unauthorized",
      data: "User did not match"
    };
  }
  Context.user = user;
  const meta = routeMap.get(Context.path);
  if (!user.role.super_admin) {
    const moduleId = `${meta?.modules[0]}`;
    const permission = user?.permissions?.[moduleId]?.ability ?? user.role?.permissions?.[moduleId]?.ability;
    if (!permission) {
      return {
        status: false,
        message: "lack of authorization",
        data: []
      };
    }
    const method = Context.request.method.toUpperCase();
    const ability = abilityHttpMap[method];
    if (!ability) {
      return {
        status: false,
        message: "invalid authorization method",
        data: []
      };
    }
    if (!permission.includes(ability)) {
      return {
        status: false,
        message: "Permission denied",
        data: []
      };
    }
  }
};

