// src/utils/otp.ts
import _crypto from "crypto";
var digits = "123456789";
var alphabets = "abcdefghijklmnopqrstuvwxyz";
var upperCase = alphabets.toUpperCase();
var specialChars = "#!&@";
var key = "LFKG:L";
function rand(min, max) {
  const random = Math.random();
  return Math.floor(random * (max - min) + min);
}
var otp_default = {
  generate: function(length, options) {
    length = length || 10;
    const generateOptions = options || {};
    generateOptions.digits = Object.prototype.hasOwnProperty.call(generateOptions, "digits") ? options.digits : true;
    generateOptions.alphabets = Object.prototype.hasOwnProperty.call(generateOptions, "alphabets") ? options.alphabets : false;
    generateOptions.upperCase = Object.prototype.hasOwnProperty.call(generateOptions, "upperCase") ? options.upperCase : false;
    generateOptions.specialChars = Object.prototype.hasOwnProperty.call(generateOptions, "specialChars") ? options.specialChars : false;
    const allowsChars = (generateOptions.digits ? digits : "") + (generateOptions.alphabets ? alphabets : "") + (generateOptions.upperCase && upperCase) + (generateOptions.specialChars && specialChars);
    let password = "";
    while (password.length < length) {
      if (password.length == 1 && password == "0") {
        password = "1";
      }
      const charIndex = rand(0, allowsChars.length - 1);
      password += allowsChars[charIndex];
    }
    return password.toString();
  },
  hash(phone, otp, expiresAfter = 3, algorithm = "sha256") {
    otp = otp.toString();
    const ttl = expiresAfter * 60 * 1000;
    const expires = Date.now() + ttl;
    const data = `${phone}.${otp}.${expires}`;
    const hashBase = _crypto.createHmac(algorithm, key).update(data).digest("hex");
    return `${hashBase}.${expires}`;
  },
  verify(phone, otp, hash2, algorithm = "sha256") {
    otp = otp.toString();
    if (!hash2.match("."))
      return false;
    let [hashValue, expires] = hash2.split(".");
    let now = Date.now();
    if (now > parseInt(expires))
      return false;
    let data = `${phone}.${otp}.${expires}`;
    let newCalculatedHash = _crypto.createHmac(algorithm, key).update(data).digest("hex");
    return newCalculatedHash === hashValue;
  },
  generateMail: (name2) => {
    let splitName = name2.split(" ");
    let firstName = splitName[0];
    let secondName = splitName[1];
    return `${secondName}${firstName}@gmail.com`.toLowerCase();
  }
};

