// src/api/admin/admins/admins.routes.ts
var admins_routes_default = createElysia({ prefix: "/admins" }).guard({
  detail: {
    tags: ["Admin"],
    summary: Summary([2 /* ROLES_AND_PERMISSIONS */])
  },
  beforeHandle: isAdminAuthenticated
}, (app) => app.get("/", async ({ query, user }) => {
  const page = Number(query.page) || 0;
  const size = Number(query.size) || 10;
  const group = query?.group;
  const deleted = query?.deleted === "yes";
  let search = query?.search;
  if (search) {
    search = new RegExp(search, "i");
  }
  const level = user.role.level;
  const filter = normalizeQuery({
    phone: { $ne: "matkactrladmin" },
    ...search && {
      $or: [
        {
          name: {
            $regex: search
          }
        },
        {
          phone: {
            $regex: search
          }
        }
      ]
    },
    ...!user?.super_admin && {
      parent: user._id.toString()
    },
    deleted
  }, user);
  console.log("\uD83D\uDE80 ~ filter:", filter);
  const [list, total] = await Promise.all([
    Admin_default.find(filter).skip(page * size).limit(size).populate("role").sort({ createdAt: -1 }).select(size >= 50 ? { _id: 1, name: 1, phone: 1, password_unhashed: 1 } : { password: 0 }).lean(),
    Admin_default.countDocuments(filter)
  ]);
  const pages = Math.ceil(total / size);
  console.log("\uD83D\uDE80 ~ pages:", pages);
  return R3("admin list data", list, true, {
    pages,
    total,
    page,
    size
  });
}, admins_schema_default.list).post("/", async ({ body, user }) => {
  console.log("Body", body);
  const children_count = await Admin_default.countDocuments({
    parent: user._id,
    deleted: false
  });
  const exitingAdmin = await Admin_default.findOne({ phone: body.phone });
  if (exitingAdmin) {
    return customError("Phone Number already used by another admin");
  }
  body.password = HashPassword(body.password_unhashed);
  if (!user.super_admin) {
    body.parent = user._id.toString();
  }
  const role = await Role_default.findById(body.role);
  if (!role)
    return customError("Invalid role");
  const entry = await Admin_default.create({
    ...body
  });
  if (role.level === 2 /* L2 */) {
    const tenantEntry = await Tenant_default.create({
      name: body.name
    });
    entry.tenant = tenantEntry._id;
    await entry.save();
  }
  if (role.level === 3 /* L3 */) {
    entry.tenant = user.tenant._id;
    await entry.save();
  }
  if (!user.super_admin) {
    const children_count2 = await Admin_default.countDocuments({
      parent: user._id,
      deleted: false
    });
    user.children_count = children_count2;
    await user.save();
  }
  return R3("entry Created", entry);
}, admins_schema_default.create).put("/", async ({ body, query, user }) => {
  body.password = HashPassword(body.password_unhashed);
  const entry = await Admin_default.findOneAndUpdate({
    _id: query.id,
    ...!user.super_admin && {
      parent: user._id.toString()
    }
  }, {
    $set: {
      ...body
    }
  }, { new: true });
  if (!user.super_admin) {
    const children_count = await Admin_default.countDocuments({
      parent: user._id,
      deleted: false
    });
    user.children_count = children_count;
    await user.save();
  }
  return R3("entry updated", entry);
}, admins_schema_default.update).delete("/", async ({ query, user }) => {
  const entry = await Admin_default.findByIdAndUpdate(query.id, {
    deleted: true
  });
  const role = await Role_default.findOne({ _id: entry?.role });
  console.log("Role", role);
  if (!entry?.super_admin && role?.name === "MASTER") {
    await Admin_default.updateMany({ parent: entry?._id }, { deleted: true });
  }
  return R3("entry updated", entry);
}, admins_schema_default.delete).post("/permission", async ({ body, query }) => {
  console.log("Calling...");
  const { permission } = body;
  const { id } = query;
  const admin = await Admin_default.findById(id).populate("role");
  const mergePermissions = {
    ...admin?.role?.permissions || {},
    ...permission
  };
  console.log("Merge Permission", mergePermissions);
  await Admin_default.findByIdAndUpdate(id, {
    $set: { permissions: mergePermissions }
  });
  return R3("Permission Added");
}, admins_schema_default.permission));

